primaryQuery:
run: order_items -> {
  group_by:
    order_year is year(created_at)
    order_month is month(created_at)
  aggregate: monthly_sales is sale_price.sum()
  order_by: order_year asc, monthly_sales desc
  calculate: rank_in_year is rank() { partition_by: order_year }
} -> {
  where: rank_in_year = 1
  select: order_year, order_month, monthly_sales
  order_by: order_year asc
}

verifyQuery:
run: order_items -> {
  group_by: order_year is year(created_at)
  nest: peak is {
    group_by: order_month is month(created_at)
    aggregate: monthly_sales is sale_price.sum()
    order_by: monthly_sales desc
    limit: 1
  }
} -> {
  select: order_year, peak.order_month, peak.monthly_sales
  order_by: order_year asc
}
